128	// 2. Pattern-based: betterleaks regex rules (260+ known secret formats)
129	// 3. Credentialed URIs: URLs containing userinfo passwords
130	// 4. Database connection strings: JDBC, keyword DSNs, and semicolon strings
131	// 5. Bounded credential key/value pairs: DB_PASSWORD=...
132	// 6. PII detection: email, phone, address patterns (only when configured via ConfigurePII)
133	// A string is redacted if ANY method flags it.
134	func String(s string) string {
135		var regions []taggedRegion
136	
137		// 1. Entropy-based detection (secrets — always on).
138		for _, loc := range secretPattern.FindAllStringIndex(s, -1) {
139			start, end := loc[0], loc[1]
140	
141			// Don't consume characters that are part of JSON/string escape sequences.
142			// Example: in "controller.go\nmodel.go", the regex could match "nmodel"
143			// (consuming the 'n' from '\n'), and after replacement the '\' would be
144			// followed by 'R' from "REDACTED", creating invalid escape '\R'.
145			// Only skip for known JSON escape letters to avoid trimming real secrets
146			// that happen to follow a literal backslash in decoded content.
147			if start > 0 && s[start-1] == '\\' {
148				switch s[start] {
149				case 'n', 't', 'r', 'b', 'f', 'u', '"', '\\', '/':
150					start++
151					if end-start < 10 {
152						continue
153					}
154				}
155			}
156	
157			if shannonEntropy(s[start:end]) > entropyThreshold {
158				regions = append(regions, taggedRegion{region: region{start, end}})
159			}
160		}
161	
162		// 2. Pattern-based detection via betterleaks (secrets — always on).
163		if d := getDetector(); d != nil {
164			for _, f := range d.DetectString(s) {
165				if f.Secret == "" {
166					continue
167				}
168				searchFrom := 0
169				for {
170					idx := strings.Index(s[searchFrom:], f.Secret)
171					if idx < 0 {
172						break
173					}
174					absIdx := searchFrom + idx
175					regions = append(regions, taggedRegion{region: region{absIdx, absIdx + len(f.Secret)}})
176					searchFrom = absIdx + len(f.Secret)
177				}
178			}
179		}
180	
181		// 3. Credentialed URIs (secrets — always on).
182		for _, loc := range credentialedURIPattern.FindAllStringIndex(s, -1) {
183			regions = append(regions, taggedRegion{region: region{loc[0], loc[1]}})
184		}
185	
186		// 4. Database and connection-string detection (secrets — always on).
187		regions = append(regions, detectConnectionStrings(s)...)
188	
189		// 5. Bounded credential key/value detection (secrets — always on).
190		regions = append(regions, detectCredentialValues(s)...)
191	
192		// 6. PII detection (opt-in — only runs when configured).
193		regions = append(regions, detectPII(getPIIConfig(), s)...)
194	
195		if len(regions) == 0 {
196			return s
197		}
198	
199		// Merge overlapping regions and build result.
200		sort.Slice(regions, func(i, j int) bool {
201			if regions[i].start != regions[j].start {
202				return regions[i].start < regions[j].start
203			}
204			if regions[i].end != regions[j].end {
205				return regions[i].end > regions[j].end // larger region first
206			}
207			return regions[i].label < regions[j].label // deterministic tie-break
208		})
209		merged := []taggedRegion{regions[0]}
210		for _, r := range regions[1:] {
211			last := &merged[len(merged)-1]
212			if r.start <= last.end {
213				if r.end > last.end {
214					last.end = r.end
215				}
216				// Keep the existing label (first/larger region wins)
217			} else {
218				merged = append(merged, r)
219			}
220		}
221	
222		var b strings.Builder
223		prev := 0
224		for _, r := range merged {
225			b.WriteString(s[prev:r.start])
226			b.WriteString(replacementToken(r.label))
227			prev = r.end
228		}
229		b.WriteString(s[prev:])
230		return b.String()
231	}
232	
233	func detectConnectionStrings(s string) []taggedRegion {
234		var regions []taggedRegion
235		for _, rule := range connectionStringRules {
236			regions = append(regions, detectConnectionStringRule(s, rule)...)
237		}
238		return regions
239	}
240	
241	func detectConnectionStringRule(s string, rule connectionStringRule) []taggedRegion {
242		var regions []taggedRegion
243		for _, loc := range rule.pattern.FindAllStringIndex(s, -1) {
244			start, end := loc[0], trimConnectionStringEnd(s, loc[0], loc[1])
245			if start >= end {
246				continue
247			}
248			if rule.hasSecret(s[start:end]) {
249				regions = append(regions, taggedRegion{region: region{start, end}})
250			}
251		}
252		return regions
253	}
254	
255	func trimConnectionStringEnd(s string, start, end int) int {
256		for end > start {
257			switch s[end-1] {
258			case '.', ',', ';', ':', '!', '?', ')', ']':
259				end--
260			default:
261				return end
262			}
263		}
264		return end
265	}
266	
267	func hasJDBCPassword(candidate string) bool {
268		if !strings.HasPrefix(strings.ToLower(candidate), "jdbc:") {
269			return false
270		}
271		return hasNonPlaceholderPasswordAssignment(candidate)
272	}
273	
274	func hasDatabaseURLSecret(candidate string) bool {
275		u, err := url.Parse(candidate)
276		if err != nil || u.Scheme == "" || u.Host == "" {
277			return false
278		}
279		for key, values := range u.Query() {
280			if !isPasswordQueryKey(key) {
281				continue
282			}
283			for _, value := range values {
284				if hasNonPlaceholderPasswordValue(value) {
285					return true
286				}
287			}
288		}
289		return false
290	}
291	
292	func isPasswordQueryKey(key string) bool {
293		return strings.EqualFold(key, "password") || strings.EqualFold(key, "pwd")
294	}
295	
296	func hasKeywordDSNPassword(candidate string) bool {
297		return keywordHostPattern.MatchString(candidate) &&
298			keywordUserPattern.MatchString(candidate) &&
299			hasNonPlaceholderPasswordAssignment(candidate)
300	}
301	
302	func hasSemicolonConnectionPassword(candidate string) bool {
303		return semicolonServerPattern.MatchString(candidate) &&
304			semicolonUserPattern.MatchString(candidate) &&
305			hasNonPlaceholderPasswordAssignment(candidate)
306	}
307	
308	func detectCredentialValues(s string) []taggedRegion {
309		var regions []taggedRegion
310		for _, loc := range credentialValuePattern.FindAllStringSubmatchIndex(s, -1) {
311			if len(loc) < 6 || loc[4] < 0 || loc[5] < 0 {
312				continue
313			}
314			start, end := unquoteRange(s, loc[4], loc[5])
315			if hasNonPlaceholderPasswordValue(s[start:end]) {
316				regions = append(regions, taggedRegion{region: region{start, end}})
317			}
318		}
319		return regions
320	}
321	
322	func unquoteRange(s string, start, end int) (int, int) {
323		if end-start < 2 {
324			return start, end
325		}
326		first, last := s[start], s[end-1]
327		if (first == '"' && last == '"') || (first == '\'' && last == '\'') {
328			return start + 1, end - 1
329		}
330		return start, end
331	}
332	
333	func hasNonPlaceholderPasswordAssignment(candidate string) bool {
334		for _, loc := range passwordAssignmentRegex.FindAllStringSubmatchIndex(candidate, -1) {
335			if len(loc) >= 4 && loc[2] >= 0 && loc[3] >= 0 {
336				start, end := unquoteRange(candidate, loc[2], loc[3])
337				if hasNonPlaceholderPasswordValue(candidate[start:end]) {
338					return true
339				}
340			}
341		}
342		return false
343	}
344	
345	func hasNonPlaceholderPasswordValue(value string) bool {
346		return value != "" && !isPlaceholderSecretValue(value)
347	}
348	
349	func isPlaceholderSecretValue(value string) bool {
350		normalized := strings.ToLower(strings.TrimSpace(value))
351		normalized = strings.Trim(normalized, `"'`)
352		if normalized == "" {
353			return true
354		}
355		if strings.HasPrefix(normalized, "${") && strings.HasSuffix(normalized, "}") {
356			return true
357		}
358		switch normalized {
359		case "redacted", "[redacted]", "<redacted>", "xxx", "xxxx", "changeme", "example":
360			return true
361		default:
362			return false
363		}
364	}
365	
366	func isCredentialJSONSecretKey(key string, credentialContext bool) bool {
367		normalized := normalizeCredentialJSONKey(key)
368		if credentialJSONKeyRegex.MatchString(normalized) {
369			return true
370		}
371		return credentialContext && genericPasswordKeyRegex.MatchString(normalized)
372	}
373	
374	func isCredentialJSONObject(obj map[string]any) bool {
375		hasHost := hasJSONKey(obj, "host", "hostname", "server", "addr", "address", "datasource", "data_source")
376		hasUser := hasJSONKey(obj, "user", "username", "userid", "user_id", "uid")
377		return hasHost && hasUser
378	}
379	
380	func hasJSONKey(obj map[string]any, keys ...string) bool {
381		for key := range obj {
382			normalized := normalizeCredentialJSONKey(key)
383			for _, want := range keys {
384				if normalized == want {
385					return true
386				}
387			}
388		}
389		return false
390	}
391	
392	func normalizeCredentialJSONKey(key string) string {
393		key = strings.ToLower(strings.TrimSpace(key))
394		key = strings.ReplaceAll(key, "-", "_")
395		key = strings.ReplaceAll(key, " ", "_")
396		return key
397	}
398	
399	// Bytes is a convenience wrapper around String for []byte content.
400	func Bytes(b []byte) []byte {
401		s := string(b)
402		redacted := String(s)
403		if redacted == s {
404			return b
405		}
406		return []byte(redacted)
407	}
