108	// region represents a byte range to redact.
109	type region struct{ start, end int }
110	
111	// taggedRegion extends region with a label for typed replacement tokens.
112	// Empty label = secret (produces "REDACTED"). Non-empty = PII (produces "[REDACTED_<LABEL>]").
113	type taggedRegion struct {
114		region
115	
116		label string
117	}
118	
119	type jsonReplacement struct {
120		key      string
121		original string
122		redacted string
123	}
124	
125	type connectionStringRule struct {
126		pattern   *regexp.Regexp
127		hasSecret func(string) bool
128	}
129	
130	var connectionStringRules = []connectionStringRule{
131		{pattern: jdbcPattern, hasSecret: hasJDBCPassword},
132		{pattern: databaseURLPattern, hasSecret: hasDatabaseURLSecret},
133		{pattern: keywordDSNPattern, hasSecret: hasKeywordDSNPassword},
134		{pattern: semicolonConnPattern, hasSecret: hasSemicolonConnectionPassword},
135	}
136	
137	// String replaces secrets and PII in s using layered detection:
138	// 1. Entropy-based: high-entropy alphanumeric sequences (threshold 4.5)
139	// 2. Pattern-based: betterleaks regex rules (260+ known secret formats)
140	// 3. Credentialed URIs: URLs containing userinfo passwords
141	// 4. Database connection strings: JDBC, keyword DSNs, and semicolon strings
142	// 5. Bounded credential key/value pairs: DB_PASSWORD=...
143	// 6. PII detection: email, phone, address patterns (only when configured via ConfigurePII)
144	// A string is redacted if ANY method flags it.
145	func String(s string) string {
146		var regions []taggedRegion
147	
148		// 1. Entropy-based detection (secrets — always on).
149		for _, loc := range secretPattern.FindAllStringIndex(s, -1) {
150			start, end := loc[0], loc[1]
151	
152			// Don't consume characters that are part of JSON/string escape sequences.
153			// Example: in "controller.go\nmodel.go", the regex could match "nmodel"
154			// (consuming the 'n' from '\n'), and after replacement the '\' would be
155			// followed by 'R' from "REDACTED", creating invalid escape '\R'.
156			// Only skip for known JSON escape letters to avoid trimming real secrets
157			// that happen to follow a literal backslash in decoded content.
158			if start > 0 && s[start-1] == '\\' {
159				switch s[start] {
160				case 'n', 't', 'r', 'b', 'f', 'u', '"', '\\', '/':
161					start++
162					if end-start < 10 {
163						continue
164					}
165				}
166			}
167	
168			if shannonEntropy(s[start:end]) > entropyThreshold {
169				regions = append(regions, taggedRegion{region: region{start, end}})
170			}
171		}
172	
173		// 2. Pattern-based detection via betterleaks (secrets — always on).
174		if d := getDetector(); d != nil {
175			for _, f := range d.DetectString(s) {
176				if f.Secret == "" {
177					continue
178				}
179				searchFrom := 0
180				for {
181					idx := strings.Index(s[searchFrom:], f.Secret)
182					if idx < 0 {
183						break
184					}
185					absIdx := searchFrom + idx
186					regions = append(regions, taggedRegion{region: region{absIdx, absIdx + len(f.Secret)}})
187					searchFrom = absIdx + len(f.Secret)
188				}
189			}
190		}
191	
192		// 3. Credentialed URIs (secrets — always on).
193		for _, loc := range credentialedURIPattern.FindAllStringIndex(s, -1) {
194			regions = append(regions, taggedRegion{region: region{loc[0], loc[1]}})
195		}
196	
197		// 4. Database and connection-string detection (secrets — always on).
198		regions = append(regions, detectConnectionStrings(s)...)
199	
200		// 5. Bounded credential key/value detection (secrets — always on).
201		regions = append(regions, detectCredentialValues(s)...)
202	
203		// 6. PII detection (opt-in — only runs when configured).
204		regions = append(regions, detectPII(getPIIConfig(), s)...)
205	
206		if len(regions) == 0 {
207			return s
208		}
209	
210		// Merge overlapping regions and build result.
211		sort.Slice(regions, func(i, j int) bool {
212			if regions[i].start != regions[j].start {
213				return regions[i].start < regions[j].start
214			}
215			if regions[i].end != regions[j].end {
216				return regions[i].end > regions[j].end // larger region first
217			}
218			return regions[i].label < regions[j].label // deterministic tie-break
219		})
220		merged := []taggedRegion{regions[0]}
221		for _, r := range regions[1:] {
222			last := &merged[len(merged)-1]
223			if r.start <= last.end {
224				if r.end > last.end {
225					last.end = r.end
226				}
227				// Keep the existing label (first/larger region wins)
228			} else {
229				merged = append(merged, r)
230			}
231		}
232	
233		var b strings.Builder
234		prev := 0
235		for _, r := range merged {
236			b.WriteString(s[prev:r.start])
237			b.WriteString(replacementToken(r.label))
238			prev = r.end
239		}
240		b.WriteString(s[prev:])
241		return b.String()
242	}
243	
244	func detectConnectionStrings(s string) []taggedRegion {
245		if !strings.ContainsRune(s, '=') {
246			return nil
247		}
248		var regions []taggedRegion
249		for _, rule := range connectionStringRules {
250			regions = append(regions, detectConnectionStringRule(s, rule)...)
251		}
252		return regions
253	}
254	
255	func detectConnectionStringRule(s string, rule connectionStringRule) []taggedRegion {
256		var regions []taggedRegion
257		for _, loc := range rule.pattern.FindAllStringIndex(s, -1) {
258			start, end := loc[0], trimConnectionStringEnd(s, loc[0], loc[1])
259			if start >= end {
260				continue
261			}
262			if rule.hasSecret(s[start:end]) {
263				regions = append(regions, taggedRegion{region: region{start, end}})
264			}
265		}
266		return regions
267	}
268	
269	func trimConnectionStringEnd(s string, start, end int) int {
270		for end > start {
271			switch s[end-1] {
272			case '.', ',', ';', ':', '!', '?', ')', ']':
273				end--
274			default:
275				return end
276			}
277		}
278		return end
279	}
