363	func isPlaceholderSecretValue(value string) bool {
364		normalized := strings.ToLower(strings.TrimSpace(value))
365		normalized = strings.Trim(normalized, `"'`)
366		if normalized == "" {
367			return true
368		}
369		if strings.HasPrefix(normalized, "${") && strings.HasSuffix(normalized, "}") {
370			return true
371		}
372		if _, ok := redactedPlaceholderForms[normalized]; ok {
373			return true
374		}
375		switch normalized {
376		case "xxx", "xxxx", "changeme", "example":
377			return true
378		default:
379			return false
380		}
381	}
