424	// JSONLBytes redacts secrets in JSONL-formatted byte content and returns
425	// the result as RedactedBytes, certifying the output has been through redaction.
426	func JSONLBytes(b []byte) (RedactedBytes, error) {
427		s := string(b)
428		redacted, err := JSONLContent(s)
429		if err != nil {
430			return RedactedBytes{}, err
431		}
432		if redacted == s {
433			return RedactedBytes{data: b}, nil
434		}
435		return RedactedBytes{data: []byte(redacted)}, nil
436	}
437	
438	// JSONLContent parses each line as JSON to determine which string values
439	// need redaction, then performs targeted replacements on the raw JSON bytes.
440	// Lines with no secrets are returned unchanged, preserving original formatting.
441	//
442	// For multi-line JSON content (e.g., pretty-printed single JSON objects like
443	// OpenCode export), the function first attempts to parse the entire content as
444	// a single JSON value. This ensures field-aware redaction (which skips ID fields)
445	// is used instead of falling back to entropy-based detection on raw text lines,
446	// which would corrupt high-entropy identifiers.
447	func JSONLContent(content string) (string, error) {
448		// Try parsing the entire content as a single JSON value first.
449		// Uses a streaming decoder to avoid copying the full content into []byte.
450		// After decoding, attempts a second Decode to confirm EOF — if it succeeds,
451		// the content is JSONL (multiple values) and we fall through to line-by-line.
452		trimmed := strings.TrimSpace(content)
453		if len(trimmed) > 0 {
454			dec := json.NewDecoder(strings.NewReader(trimmed))
455			var parsed any
456			if err := dec.Decode(&parsed); err == nil && isSingleJSONValue(dec) {
457				// Content is a single JSON value (object/array) — redact field-aware.
458				result, err := applyJSONReplacements(content, collectJSONLReplacements(parsed))
459				if err != nil {
460					return "", err
461				}
462				return result, nil
463			}
464		}
465	
466		// Fall back to line-by-line JSONL processing.
467		lines := strings.Split(content, "\n")
468		var b strings.Builder
469		for i, line := range lines {
470			if i > 0 {
471				b.WriteByte('\n')
472			}
473			lineTrimmed := strings.TrimSpace(line)
474			if lineTrimmed == "" {
475				b.WriteString(line)
476				continue
477			}
478			var parsed any
479			if err := json.Unmarshal([]byte(lineTrimmed), &parsed); err != nil {
480				b.WriteString(String(line))
481				continue
482			}
483			result, err := applyJSONReplacements(line, collectJSONLReplacements(parsed))
484			if err != nil {
485				return "", err
486			}
487			b.WriteString(result)
488		}
489		return b.String(), nil
490	}
491	
492	// applyJSONReplacements applies collected (original, redacted) string pairs
493	// to the raw JSON text, replacing JSON-encoded originals with their redacted forms.
494	// Returns s unchanged if repls is empty.
495	func applyJSONReplacements(s string, repls []jsonReplacement) (string, error) {
496		if len(repls) == 0 {
497			return s, nil
498		}
499		for _, r := range repls {
500			origJSON, err := jsonEncodeString(r.original)
501			if err != nil {
502				return "", err
503			}
504			replJSON, err := jsonEncodeString(r.redacted)
505			if err != nil {
506				return "", err
507			}
508			if r.key == "" {
509				s = strings.ReplaceAll(s, origJSON, replJSON)
510				continue
511			}
512			keyJSON, err := jsonEncodeString(r.key)
513			if err != nil {
514				return "", err
515			}
516			s = replaceKeyedJSONValue(s, keyJSON, origJSON, replJSON)
517		}
518		return s, nil
519	}
520	
521	// replaceKeyedJSONValue replaces every occurrence of origJSON that follows
522	// keyJSON + optional whitespace + ':' + optional whitespace. Restricts
523	// substitution to value positions so a key's own redacted text is not
524	// rewritten when it collides with another field's value.
525	func replaceKeyedJSONValue(s, keyJSON, origJSON, replJSON string) string {
526		if !strings.Contains(s, keyJSON) {
527			return s
528		}
529		var b strings.Builder
530		b.Grow(len(s))
531		i := 0
532		for i < len(s) {
533			j := strings.Index(s[i:], keyJSON)
534			if j < 0 {
535				b.WriteString(s[i:])
536				break
537			}
538			keyEnd := i + j + len(keyJSON)
539			b.WriteString(s[i : i+j])
540			b.WriteString(keyJSON)
541			p := keyEnd
542			for p < len(s) && isJSONWhitespace(s[p]) {
543				p++
544			}
545			if p >= len(s) || s[p] != ':' {
546				i = keyEnd
547				continue
548			}
549			p++
550			for p < len(s) && isJSONWhitespace(s[p]) {
551				p++
552			}
553			if p+len(origJSON) <= len(s) && s[p:p+len(origJSON)] == origJSON {
554				b.WriteString(s[keyEnd:p])
555				b.WriteString(replJSON)
556				i = p + len(origJSON)
557				continue
558			}
559			i = keyEnd
560		}
561		return b.String()
562	}
563	
564	func isJSONWhitespace(c byte) bool {
565		return c == ' ' || c == '\t' || c == '\n' || c == '\r'
566	}
567	
568	// isSingleJSONValue returns true if the decoder has reached EOF (no more
569	// top-level values). This distinguishes a single JSON value (e.g., pretty-printed
570	// object) from JSONL (multiple concatenated values). We attempt a second Decode
571	// and require io.EOF rather than relying on dec.More(), which is documented for
572	// use inside arrays/objects and not for top-level value boundaries.
573	func isSingleJSONValue(dec *json.Decoder) bool {
574		var discard json.RawMessage
575		return dec.Decode(&discard) == io.EOF
576	}
577	
578	// collectJSONLReplacements walks a parsed JSON value and collects unique string
579	// replacements for values that need redaction.
580	func collectJSONLReplacements(v any) []jsonReplacement {
581		seen := make(map[string]bool)
582		var repls []jsonReplacement
583		var walk func(key string, credentialContext bool, v any)
584		walk = func(key string, credentialContext bool, v any) {
585			switch val := v.(type) {
586			case map[string]any:
587				if shouldSkipJSONLObject(val) {
588					return
589				}
590				childCredentialContext := credentialContext || isCredentialJSONObject(val)
591				for k, child := range val {
592					if shouldSkipJSONLField(k) {
593						continue
594					}
595					walk(k, childCredentialContext, child)
596				}
597			case []any:
598				for _, child := range val {
599					walk("", credentialContext, child)
600				}
601			case string:
602				redacted := String(val)
603				if redacted == val && isCredentialJSONSecretKey(key, credentialContext) && hasNonPlaceholderPasswordValue(val) {
604					redacted = RedactedPlaceholder
605				}
606				if redacted != val {
607					seenKey := key + "\x00" + val
608					if !seen[seenKey] {
609						seen[seenKey] = true
610						repls = append(repls, jsonReplacement{key: key, original: val, redacted: redacted})
611					}
612				}
613			}
614		}
615		walk("", false, v)
616		return repls
617	}
618	
619	// shouldSkipJSONLField returns true if a JSON key should be excluded from scanning/redaction.
620	// Skips "signature" (exact), ID fields (ending in "id"/"ids"), and common path/directory fields.
621	func shouldSkipJSONLField(key string) bool {
622		if key == "signature" {
623			return true
624		}
625		lower := strings.ToLower(key)
626	
627		// Skip ID fields
628		if strings.HasSuffix(lower, "id") || strings.HasSuffix(lower, "ids") {
629			return true
630		}
631	
632		// Skip common path and directory fields from agent transcripts.
633		// These appear frequently in tool calls and are structural, not secrets.
634		switch lower {
635		case "filepath", "file_path", "cwd", "root", "directory", "dir", "path":
636			return true
637		}
638	
639		return false
640	}
641	
642	// shouldSkipJSONLObject returns true if the object has "type":"image" or "type":"image_url".
643	func shouldSkipJSONLObject(obj map[string]any) bool {
644		t, ok := obj["type"].(string)
645		return ok && (strings.HasPrefix(t, "image") || t == "base64")
646	}
647	
648	func shannonEntropy(s string) float64 {
649		if len(s) == 0 {
650			return 0
651		}
652		freq := make(map[byte]int)
653		for i := range len(s) {
654			freq[s[i]]++
655		}
656		length := float64(len(s))
657		var entropy float64
658		for _, count := range freq {
659			p := float64(count) / length
660			entropy -= p * math.Log2(p)
661		}
662		return entropy
663	}
664	
665	// jsonEncodeString returns the JSON encoding of s without HTML escaping.
666	func jsonEncodeString(s string) (string, error) {
667		var buf bytes.Buffer
668		enc := json.NewEncoder(&buf)
669		enc.SetEscapeHTML(false)
670		if err := enc.Encode(s); err != nil {
671			return "", fmt.Errorf("json encode string: %w", err)
672		}
673		return strings.TrimSuffix(buf.String(), "\n"), nil
674	}
